selector_to_html = {"a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.turbine._pyturbo._row\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo._row\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_row</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">definition</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">row</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_points</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.turbine._pyturbo._MEASURE_POINTS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo._MEASURE_POINTS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_MEASURE_POINTS</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">400</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.turbine._pyturbo._section\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo._section\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_section</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">row</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outlet</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stagger</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>One section\u2019s suction and pressure sides as <code class=\"docutils literal notranslate\"><span class=\"pre\">(axial,</span> <span class=\"pre\">pitchwise)</span></code> from its LE.</p><p>Returns the two sides at <code class=\"docutils literal notranslate\"><span class=\"pre\">n</span></code> points and the outline at the measuring\nresolution.</p></dd>", "a[href=\"#module-pyskyfire.turbine._pyturbo\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.turbine._pyturbo<a class=\"headerlink\" href=\"#module-pyskyfire.turbine._pyturbo\" title=\"Link to this heading\">\u00b6</a></h1><p>Turbine blade sections from pyTurbo 1.3.8, wrapped onto the annulus.</p><p>pyTurbo\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">Airfoil2D</span></code> draws a cascade section flowing top to bottom (-y),\nwith the trailing edge at the origin and angles from axial. It turns the flow\ntoward +x. This package\u2019s angles are positive in the rotation direction, and\na row can turn the flow either way (a stator towards the rotation, a rotor\nback against it), so each section is drawn turning the pyTurbo way and\nmirrored where the row turns the other way.</p>", "a[href=\"#pyskyfire.turbine._pyturbo.build_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo.build_geometry\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">build_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">definition</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_points</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.turbine._pyturbo._LEADING_EDGE\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo._LEADING_EDGE\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_LEADING_EDGE</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">0.6666666666666666</span></span></dt><dd></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.turbine._pyturbo._require_pyturbo\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine._pyturbo._require_pyturbo\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine._pyturbo.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_require_pyturbo</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
